import re
def jobs(n):
    b=open(".github/workflows/"+n).read().split("\njobs:\n",1)[1]
    p=re.split(r"(?m)^  ([a-z-]+):\n","\n"+b)
    return {p[i]:re.search(r"(?m)^    runs-on: (.+)$",p[i+1]).group(1).strip() for i in range(1,len(p)-1,2)}
g=jobs("gate.yml");default=re.search(r"runner:\n(?:.*\n)*?        default: \"([^\"]+)\"",open(".github/workflows/gate.yml").read()).group(1)
for label,val in (("default",default),("ubicloud","ubicloud-standard-2")):
    r={k:(val if v=="${{ inputs.runner }}" else v) for k,v in g.items()}
    r["audit"]=jobs("audit.yml")["audit"];r["dashboard"]=jobs("dashboard.yml")["dashboard"]
    print(label,"tests=%s measure=%s story-gate=%s audit=%s dashboard=%s"%(r["tests"],r["measure"],r["story-gate"],r["audit"],r["dashboard"]))
